/**
 * @file kratos_mesh.hpp
 * @brief The KRATOS mesh backend: `meshioplusplus::KratosMesh`, the uniform
 * mesh API implemented over a Kratos-style `ModelPart`.
 *
 * Selected by `MESHIOPLUSPLUS_MESH_BACKEND=KRATOS` (see `mesh.hpp`). Format
 * readers ingest into a canonical staging structure (a `NativeMesh` — same
 * canonical Float64/Int64 storage), and the `ModelPart` is **materialized
 * lazily** on the first `GetModelPart()` call:
 *
 *  - Nodes get Ids `index + 1` (z = 0-padded for 2-D points).
 *  - Cell blocks whose topological dimension equals the mesh's maximum
 *    become **Elements**; lower-dimension blocks become **Conditions** (the
 *    Kratos convention, matching `src/meshioplusplus/mdpa/_mdpa.py`), each
 *    kind Id-numbered 1..N in block order, with default Kratos names from
 *    `kratos_names.hpp`.
 *  - `point_data` becomes nodal data; `cell_data` becomes elemental /
 *    conditional data (concatenated per kind, entity order); `field_data`
 *    stays on the staging mesh (Kratos has no equivalent).
 *  - **Integer tag arrays** under well-known names (`gmsh:physical`,
 *    `su2:tag`, `medit:ref`, `cell_tags`, ...) automatically become named
 *    SubModelParts (`gmsh_physical_1`, ...) containing the tagged entities
 *    and their nodes — disable with `SetBuildSubModelPartsFromTags(false)`.
 *    The tag arrays remain as elemental/conditional data either way, so
 *    writer round-trips are unaffected.
 *  - **Ragged blocks** (polygon/polyhedron) have no ModelPart geometry;
 *    they stay in staging pass-through (round-trips keep working) and do
 *    not become entities.
 *
 * Writer accessors serve from the staging structure, so a read -> write
 * round-trip never pays for (or builds) the ModelPart at all, and output
 * bytes match the NATIVE backend exactly. After mutating the ModelPart
 * directly, call `InvalidateBlocks()`: the staging is then rebuilt from the
 * ModelPart on the next accessor use (consecutive same-type Elements are
 * grouped into blocks, then Conditions; ragged pass-through blocks and
 * SubModelPart structure are not representable back and are dropped —
 * a documented sharp edge of the mutation path).
 */

// System includes
#include <algorithm>
#include <cstdint>
#include <cstring>
#include <memory>
#include <string>
#include <utility>
#include <vector>

// Project includes

namespace meshioplusplus {

/**
 * @brief The KRATOS mesh backend (aliased to `meshioplusplus::Mesh` when
 * `MESHIOPLUSPLUS_MESH_BACKEND_KRATOS` is defined). See the file-level
 * comment for the staging/materialization design.
 */
class KratosMesh {
public:
    /** @brief Cell-data names treated as entity tags for automatic SubModelParts. */
    static const std::vector<std::string>& KnownTagKeys() {
        static const std::vector<std::string> keys = {
            "cell_tags", "gmsh:physical", "su2:tag", "medit:ref",  "avsucd:material", "freefem:ref",
            "mfm:ref",   "netgen:index",  "pf3:ref", "tetgen:ref", "ugrid:ref",       "unv:pid",
        };
        return keys;
    }

    // --- uniform API: reader-side ingestion (forwarded to staging) ---------

    void AssignPoints(NDArray points) {
        ResetModelPartOnly();
        mStage.AssignPoints(std::move(points));
    }
    void AddCellBlock(std::string type, NDArray conn) {
        ResetModelPartOnly();
        mStage.AddCellBlock(std::move(type), std::move(conn));
    }
    void AddPolygonBlock(std::string type, std::vector<std::vector<std::int64_t>> rows) {
        ResetModelPartOnly();
        mStage.AddPolygonBlock(std::move(type), std::move(rows));
    }
    void AddPolyhedronBlock(std::string type,
                            std::vector<std::vector<std::vector<std::int64_t>>> cells) {
        ResetModelPartOnly();
        mStage.AddPolyhedronBlock(std::move(type), std::move(cells));
    }
    void AddPointData(std::string name, NDArray data) {
        ResetModelPartOnly();
        mStage.AddPointData(std::move(name), std::move(data));
    }
    void AddCellData(std::string name, std::vector<NDArray> blocks) {
        ResetModelPartOnly();
        mStage.AddCellData(std::move(name), std::move(blocks));
    }
    void AppendCellData(const std::string& rName, NDArray block) {
        ResetModelPartOnly();
        mStage.AppendCellData(rName, std::move(block));
    }
    void AddFieldData(std::string name, NDArray data) {
        ResetModelPartOnly();
        mStage.AddFieldData(std::move(name), std::move(data));
    }

    // --- uniform API: writer-side accessors (staging, stale-synced) --------

    using CellView = NativeMesh::CellView;

    std::size_t NumPoints() const { return Stage().NumPoints(); }
    std::size_t PointDim() const { return Stage().PointDim(); }
    const NDArray& Points() const { return Stage().Points(); }
    std::size_t NumCellBlocks() const { return Stage().NumCellBlocks(); }
    CellView Cells(std::size_t i) const { return Stage().Cells(i); }
    detail::CellBlockRange<KratosMesh> CellRange() const {
        return detail::CellBlockRange<KratosMesh>(*this);
    }

    std::vector<std::string> PointDataNames() const { return Stage().PointDataNames(); }
    std::size_t NumPointData() const { return Stage().NumPointData(); }
    bool HasPointData(const std::string& rName) const { return Stage().HasPointData(rName); }
    const NDArray& PointData(const std::string& rName) const { return Stage().PointData(rName); }

    std::vector<std::string> CellDataNames() const { return Stage().CellDataNames(); }
    std::size_t NumCellData() const { return Stage().NumCellData(); }
    bool HasCellData(const std::string& rName) const { return Stage().HasCellData(rName); }
    const NDArray& CellData(const std::string& rName, std::size_t block) const {
        return Stage().CellData(rName, block);
    }
    std::size_t CellDataNumBlocks(const std::string& rName) const {
        return Stage().CellDataNumBlocks(rName);
    }

    std::vector<std::string> FieldDataNames() const { return Stage().FieldDataNames(); }
    std::size_t NumFieldData() const { return Stage().NumFieldData(); }
    bool HasFieldData(const std::string& rName) const { return Stage().HasFieldData(rName); }
    const NDArray& FieldData(const std::string& rName) const { return Stage().FieldData(rName); }

    // --- KRATOS-specific surface -------------------------------------------

    /**
     * @brief The ModelPart view of this mesh, materialized on first call.
     * @return The root `ModelPart` (named "Main").
     */
    ModelPart& GetModelPart() {
        EnsureStage();  // a pending user mutation must be folded in first
        if (!mMaterialized)
            Materialize();
        return *mpRoot;
    }
    /** @brief Whether `GetModelPart()` has materialized the ModelPart yet. */
    bool IsMaterialized() const { return mMaterialized; }

    /**
     * @brief Declare that the ModelPart was mutated directly: the block/
     * point staging is rebuilt from the ModelPart on the next accessor use
     * (grouping consecutive same-type Elements, then Conditions; ragged
     * pass-through blocks and SubModelPart structure are dropped).
     */
    void InvalidateBlocks() {
        if (mMaterialized)
            mStale = true;
    }

    /**
     * @brief Enable/disable automatic tag -> SubModelPart creation at
     * materialization (default: enabled). Call before `GetModelPart()`.
     */
    void SetBuildSubModelPartsFromTags(bool enable) {
        mTagsToSubModelParts = enable;
        if (mMaterialized && !mStale) {
            mMaterialized = false;  // re-materialize with the new setting
            mpRoot.reset();
        }
    }
    bool BuildSubModelPartsFromTags() const { return mTagsToSubModelParts; }

private:
    /** @brief Per staged block: what it became in the ModelPart. */
    struct BlockRecord {
        enum class Kind { Element, Condition, Ragged } mKind = Kind::Ragged;
        IndexType mFirstId = 0;  // first entity Id (Element/Condition kinds)
        std::size_t mCount = 0;
    };

    void ResetModelPartOnly() {
        // Ingestion after materialization restarts the ModelPart view.
        if (mMaterialized) {
            mpRoot.reset();
            mRecords.clear();
            mMaterialized = false;
            mStale = false;
        }
    }

    const NativeMesh& Stage() const {
        EnsureStage();
        return mStage;
    }
    void EnsureStage() const {
        if (mStale) {
            RebuildStageFromModelPart();
            mStale = false;
        }
    }

    /** @brief Topological dimension of a staged block (Custom via the name table). */
    static int BlockDimension(const NativeCellBlock& rBlock) {
        const int dim = cell_type_dimension(rBlock.mType);
        if (dim >= 0)
            return dim;
        auto it = topological_dimension().find(rBlock.mTypeName);
        if (it != topological_dimension().end())
            return it->second;
        return 3;
    }

    void Materialize() {
        mpRoot = std::make_unique<ModelPart>("Main");
        mRecords.clear();
        ModelPart& r_mp = *mpRoot;

        // Nodes: Id = index + 1, z zero-padded for 2-D points.
        const NDArray& points = mStage.Points();
        const std::size_t npts = mStage.NumPoints();
        const std::size_t dim = mStage.PointDim();
        const double* p = npts ? points.As<double>() : nullptr;
        for (std::size_t i = 0; i < npts; ++i)
            r_mp.CreateNewNode(i + 1, p[i * dim], dim > 1 ? p[i * dim + 1] : 0.0,
                               dim > 2 ? p[i * dim + 2] : 0.0);

        // Elements/Conditions split: block dim == mesh max dim -> Element.
        int mesh_dim = 0;
        for (const auto& r_b : mStage.Blocks())
            mesh_dim = std::max(mesh_dim, BlockDimension(r_b));

        IndexType next_elem = 1, next_cond = 1;
        std::size_t n_elem_rows = 0, n_cond_rows = 0;
        for (const auto& r_b : mStage.Blocks()) {
            BlockRecord rec;
            rec.mCount = r_b.NumCells();
            if (r_b.IsRagged()) {
                rec.mKind = BlockRecord::Kind::Ragged;  // pass-through, no entities
            } else {
                const bool is_elem = BlockDimension(r_b) == mesh_dim;
                rec.mKind = is_elem ? BlockRecord::Kind::Element : BlockRecord::Kind::Condition;
                rec.mFirstId = is_elem ? next_elem : next_cond;
                const std::size_t n = r_b.NumCells();
                const std::size_t k = r_b.mConn.Ndim() >= 2 ? r_b.mConn.Shape()[1] : 0;
                const std::int64_t* conn = r_b.mConn.As<std::int64_t>();
                for (std::size_t c = 0; c < n; ++c) {
                    std::vector<IndexType> ids(k);
                    for (std::size_t j = 0; j < k; ++j)
                        ids[j] = static_cast<IndexType>(conn[c * k + j]) + 1;
                    if (is_elem)
                        r_mp.CreateNewElement(r_b.mType, next_elem++, std::move(ids));
                    else
                        r_mp.CreateNewCondition(r_b.mType, next_cond++, std::move(ids));
                }
                (is_elem ? n_elem_rows : n_cond_rows) += n;
            }
            mRecords.push_back(rec);
        }

        // point_data -> nodal data (shared row order: node index).
        for (const auto& r_name : mStage.PointDataNames())
            r_mp.SetNodalData(r_name, mStage.PointData(r_name));

        // cell_data -> elemental/conditional data, concatenated per kind in
        // entity order (== block order within each kind).
        for (const auto& r_name : mStage.CellDataNames()) {
            if (mStage.CellDataNumBlocks(r_name) != mStage.NumCellBlocks())
                continue;  // partial data cannot be aligned with entities
            if (n_elem_rows > 0) {
                NDArray col = ConcatKind(r_name, BlockRecord::Kind::Element, n_elem_rows);
                if (col.Size() > 0)
                    r_mp.SetElementalData(r_name, std::move(col));
            }
            if (n_cond_rows > 0) {
                NDArray col = ConcatKind(r_name, BlockRecord::Kind::Condition, n_cond_rows);
                if (col.Size() > 0)
                    r_mp.SetConditionalData(r_name, std::move(col));
            }
        }

        // Integer tags -> SubModelParts (unless disabled).
        if (mTagsToSubModelParts)
            for (const auto& r_key : KnownTagKeys())
                if (mStage.HasCellData(r_key) &&
                    mStage.CellDataNumBlocks(r_key) == mStage.NumCellBlocks())
                    BuildSubModelPartsFor(r_key);

        mMaterialized = true;
    }

    /** @brief Concatenate one cell-data name's arrays over blocks of one kind. */
    NDArray ConcatKind(const std::string& rName, BlockRecord::Kind kind,
                       std::size_t totalRows) const {
        // Determine dtype/trailing shape from the first contributing block;
        // bail out (empty result) if the blocks disagree on dtype.
        const NDArray* p_first = nullptr;
        for (std::size_t b = 0; b < mRecords.size(); ++b) {
            if (mRecords[b].mKind != kind || mRecords[b].mCount == 0)
                continue;
            const NDArray& blk = mStage.CellData(rName, b);
            if (!p_first)
                p_first = &blk;
            else if (blk.Dtype() != p_first->Dtype())
                return NDArray{};
        }
        if (!p_first || totalRows == 0)
            return NDArray{};
        std::vector<std::size_t> shape = p_first->Shape();
        if (shape.empty())
            shape = {0};
        shape[0] = totalRows;
        NDArray out = NDArray::Uninit(p_first->Dtype(), shape);
        std::size_t off = 0;
        for (std::size_t b = 0; b < mRecords.size(); ++b) {
            if (mRecords[b].mKind != kind)
                continue;
            const NDArray& blk = mStage.CellData(rName, b);
            std::memcpy(out.Data() + off, blk.Data(), blk.Nbytes());
            off += blk.Nbytes();
        }
        return out;
    }

    void BuildSubModelPartsFor(const std::string& rKey) {
        // Only integer-kind scalar-per-cell arrays qualify as tags.
        for (std::size_t b = 0; b < mRecords.size(); ++b) {
            if (mRecords[b].mKind == BlockRecord::Kind::Ragged)
                continue;
            const NDArray& a = mStage.CellData(rKey, b);
            if (detail::is_float_dtype(a.Dtype()) || a.Size() != mRecords[b].mCount)
                return;
        }
        std::string prefix = rKey;
        for (char& r_c : prefix)
            if (r_c == ':')
                r_c = '_';

        // tag value -> (element ids, condition ids)
        struct Members {
            std::vector<IndexType> mElems, mConds;
        };
        std::unordered_map<std::int64_t, Members> groups;
        std::vector<std::int64_t> order;  // first-seen order for determinism
        for (std::size_t b = 0; b < mRecords.size(); ++b) {
            const BlockRecord& rec = mRecords[b];
            if (rec.mKind == BlockRecord::Kind::Ragged)
                continue;
            const NDArray& a = mStage.CellData(rKey, b);
            for (std::size_t c = 0; c < rec.mCount; ++c) {
                const std::int64_t tag = detail::read_int(a, c);
                auto [it, inserted] = groups.try_emplace(tag);
                if (inserted)
                    order.push_back(tag);
                if (rec.mKind == BlockRecord::Kind::Element)
                    it->second.mElems.push_back(rec.mFirstId + c);
                else
                    it->second.mConds.push_back(rec.mFirstId + c);
            }
        }
        for (const std::int64_t tag : order) {
            const std::string name = prefix + "_" + std::to_string(tag);
            if (mpRoot->HasSubModelPart(name))
                continue;  // an earlier tag key already claimed the name
            ModelPart& r_smp = mpRoot->CreateSubModelPart(name);
            const Members& r_m = groups.at(tag);
            r_smp.AddElements(r_m.mElems);
            r_smp.AddConditions(r_m.mConds);
            // Kratos convention: a sub model part contains its entities' nodes.
            std::vector<IndexType> node_ids;
            detail::IdList seen;
            for (IndexType eid : r_m.mElems)
                for (IndexType nid : mpRoot->GetElement(eid).NodeIds())
                    if (seen.Add(nid))
                        node_ids.push_back(nid);
            for (IndexType cid : r_m.mConds)
                for (IndexType nid : mpRoot->GetCondition(cid).NodeIds())
                    if (seen.Add(nid))
                        node_ids.push_back(nid);
            r_smp.AddNodes(node_ids);
        }
    }

    void RebuildStageFromModelPart() const {
        const ModelPart& r_mp = *mpRoot;
        NativeMesh fresh;

        // Points from nodes in container order; node Id -> 0-based index.
        const std::size_t n = r_mp.Nodes().Size();
        NDArray pts = NDArray::Uninit(DType::Float64, {n, 3});
        double* p = pts.As<double>();
        std::size_t i = 0;
        for (const Node& r_node : r_mp.Nodes()) {
            p[i * 3 + 0] = r_node.X();
            p[i * 3 + 1] = r_node.Y();
            p[i * 3 + 2] = r_node.Z();
            ++i;
        }
        fresh.AssignPoints(std::move(pts));

        // Consecutive same-type runs -> blocks (Elements first, then
        // Conditions), matching the materialization convention.
        mRecords.clear();
        AppendEntityBlocks(r_mp, r_mp.Elements(), BlockRecord::Kind::Element, fresh);
        AppendEntityBlocks(r_mp, r_mp.Conditions(), BlockRecord::Kind::Condition, fresh);

        // Nodal data -> point_data; elemental/conditional -> per-block slices.
        for (const auto& r_name : r_mp.NodalDataNames())
            fresh.AddPointData(r_name, r_mp.GetNodalData(r_name));
        RestoreCellData(r_mp.ElementalDataNames(), BlockRecord::Kind::Element, r_mp, fresh);
        RestoreCellData(r_mp.ConditionalDataNames(), BlockRecord::Kind::Condition, r_mp, fresh);
        for (const auto& r_name : mStage.FieldDataNames())
            fresh.AddFieldData(r_name, mStage.FieldData(r_name));

        mStage = std::move(fresh);
    }

    template <class TContainer>
    void AppendEntityBlocks(const ModelPart& rMp, const TContainer& rEntities,
                            BlockRecord::Kind kind, NativeMesh& rOut) const {
        std::vector<const GeometricalEntity*> run;
        auto flush = [&]() {
            if (run.empty())
                return;
            const std::size_t nc = run.size();
            const std::size_t k = run.front()->NumberOfNodes();
            NDArray conn = NDArray::Uninit(DType::Int64, {nc, k});
            std::int64_t* c = conn.As<std::int64_t>();
            for (std::size_t r = 0; r < nc; ++r)
                for (std::size_t j = 0; j < k; ++j)
                    c[r * k + j] =
                        static_cast<std::int64_t>(rMp.Nodes().IndexOf(run[r]->NodeIds()[j]));
            const CellType type = run.front()->Type();
            BlockRecord rec;
            rec.mKind = kind;
            rec.mFirstId = run.front()->Id();
            rec.mCount = nc;
            mRecords.push_back(rec);
            rOut.AddCellBlock(cell_type_name(type), std::move(conn));
            run.clear();
        };
        for (const auto& r_e : rEntities) {
            if (!run.empty() && (run.front()->Type() != r_e.Type() ||
                                 run.front()->NumberOfNodes() != r_e.NumberOfNodes()))
                flush();
            run.push_back(&r_e);
        }
        flush();
    }

    void RestoreCellData(const std::vector<std::string>& rNames, BlockRecord::Kind kind,
                         const ModelPart& rMp, NativeMesh& rOut) const {
        for (const auto& r_name : rNames) {
            const NDArray& col = kind == BlockRecord::Kind::Element
                                     ? rMp.GetElementalData(r_name)
                                     : rMp.GetConditionalData(r_name);
            const std::size_t ncols = col.Ndim() >= 2 ? col.Shape()[1] : 1;
            const std::size_t isz = dtype_size(col.Dtype());
            std::size_t row = 0;
            for (const auto& rec : mRecords) {
                if (rec.mKind != kind)
                    continue;
                std::vector<std::size_t> shape = col.Shape();
                if (shape.empty())
                    shape = {0};
                shape[0] = rec.mCount;
                NDArray slice = NDArray::Uninit(col.Dtype(), shape);
                std::memcpy(slice.Data(), col.Data() + row * ncols * isz, rec.mCount * ncols * isz);
                row += rec.mCount;
                rOut.AppendCellData(r_name, std::move(slice));
            }
        }
    }

    mutable NativeMesh mStage;  // staging + writer-serving storage
    std::unique_ptr<ModelPart> mpRoot;
    mutable std::vector<BlockRecord> mRecords;
    bool mMaterialized = false;
    mutable bool mStale = false;
    bool mTagsToSubModelParts = true;
};

}  // namespace meshioplusplus
// ===== end cpp/include/meshioplusplus/backends/kratos_mesh.hpp =====
// ===== begin cpp/include/meshioplusplus/detail/map_order.hpp =====
/**
 * @file map_order.hpp
 * @brief Deterministic iteration order for the `Mesh` data maps.
 *
 * `Mesh::point_data`/`cell_data`/`field_data` are `std::unordered_map` (O(1)
 * lookup, no ordering guarantee), but their key order is observable — it drives
 * Python dict key order and the on-disk field/variable order of several writers
 * (VTU, XDMF, Exodus, Tecplot, HMF) as well as medit's "first int field"
 * selection. `sorted_keys` recovers that order explicitly at each such
 * consumption site, decoupling "how we store" from "how we emit" so output stays
 * byte-identical regardless of the storage container.
 */

// System includes
#include <algorithm>
#include <vector>

namespace meshioplusplus {
namespace detail {

/**
 * @brief Collect a map's keys in sorted order.
 * @tparam Map An associative container (ordered or unordered).
 * @param m The map whose keys to enumerate.
 * @return The keys of @p m sorted ascending.
 */
template <class Map>
std::vector<typename Map::key_type> sorted_keys(const Map& rM) {
    std::vector<typename Map::key_type> keys;
    keys.reserve(rM.size());
    for (const auto& kv : rM)
        keys.push_back(kv.first);
    std::sort(keys.begin(), keys.end());
    return keys;
}

}  // namespace detail
}  // namespace meshioplusplus
// ===== end cpp/include/meshioplusplus/detail/map_order.hpp =====
// ===== begin cpp/include/meshioplusplus/backends/meshio_mesh.hpp =====
/**
 * @file meshio_mesh.hpp
 * @brief The MESHIO mesh backend: `meshioplusplus::Mesh` and
 * `meshioplusplus::CellBlock`, the meshio-mirroring in-memory representation.
 *
 * This is the default mesh backend (see `mesh.hpp` for the compile-time
 * dispatch and `mesh_api.hpp` for the uniform format-facing API it
 * implements), and the only one compatible with the pybind11 extension —
 * `bindings/np_conversions.hpp` is written against these exact members.
 *
 * It mirrors the fields of the pure-Python `meshio.Mesh`: it is the type
 * every C++ format reader produces and every C++ format writer consumes.
 * The pybind11 binding layer (`bindings/np_conversions.hpp`) converts between
 * this type and the pure-Python `meshio.Mesh` at the I/O boundary, following
 * a "zero-copy at the boundary" strategy: `py_to_mesh` builds non-owning
 * `NDArray` *views* over the caller's numpy buffers (write path, no input
 * copy) and `mesh_to_py` moves each `NDArray`'s owned buffer into a capsule
 * backing a writeable numpy array (read path, no output copy).
 *
 * The conversion layer carries `points`, `cells`, `point_data`, `cell_data`,
 * and `field_data` — but deliberately **not** `mesh.info`, `cell_sets`, or
 * `point_sets`, which are custom attributes that live only on the Python
 * `Mesh`. Formats that need those either defer entirely to the Python
 * fallback or carry the extra data out-of-band via a side-channel struct
 * that the binding `setattr`s onto the Python `Mesh` object after
 * conversion (e.g. `MedInfo`/`AnsysInfo` for `point_sets`/`cell_sets`,
 * `OpenFoamInfo` for `cell_tags`).
 */

// System includes
#include <cstdint>
#include <string>
#include <unordered_map>
#include <utility>
#include <vector>

// Project includes

namespace meshioplusplus {

/**
 * @brief One homogeneous block of cells of a single meshio cell type.
 *
 * Mirrors a Python `meshio.CellBlock`. Most blocks are *rectangular*: `mData`
 * is a `(num_cells, nodes_per_cell)` integer `NDArray` of node indices.
 * Some formats, however, produce cells that cannot be described by a fixed
 * nodes-per-cell count, so `CellBlock` also carries two optional *ragged*
 * (jagged) representations:
 *
 *  - `mPolygonRows` — 1-level ragged: a `"polygon"` block whose cells have
 *    varying node counts (e.g. MED POG Voronoi meshes). Row `i` is the list
 *    of node ids for cell `i`.
 *  - `mPolyhedronRows` — 2-level ragged: a `"polyhedron"` block. Cell `i` is
 *    a list of faces, each face itself a list of node ids.
 *
 * Exactly one of `mData`, `mPolygonRows`, `mPolyhedronRows` is populated per
 * block (see `IsRagged()`); the unused members are left empty, so ordinary
 * rectangular blocks (the overwhelming majority) are unaffected. Zero-copy
 * numpy conversion at the binding boundary only applies to the rectangular
 * `mData` case — ragged blocks are always *copied* across the boundary, and
 * `py_to_mesh`'s `allow_ragged` flag is off by default so a rectangular-only
 * writer given a ragged mesh safely throws and triggers the Python fallback;
 * only ragged-aware bindings (e.g. MED write) opt in.
 */
struct CellBlock {
    std::string mType;  // meshio cell type, e.g. "triangle"
    NDArray mData;      // (num_cells, nodes_per_cell), integer dtype
    std::vector<std::string> mTags;

    // Ragged (jagged) representations, used only for cell types whose rows do
    // not fit a rectangular buffer. Exactly one of `mData` / `mPolygonRows` /
    // `mPolyhedronRows` is populated per block; the two ragged members are
    // empty for every rectangular block (all rectangular formats unaffected).
    //
    //  * mPolygonRows    — 1-level ragged: a "polygon" block whose cells have
    //                      varying node counts (e.g. MED POG Voronoi meshes).
    //                      Row i = mPolygonRows[i] = node ids of cell i.
    //  * mPolyhedronRows — 2-level ragged: a "polyhedron" block. Cell i is a
    //                      list of faces; each face is a list of node ids.
    std::vector<std::vector<std::int64_t>> mPolygonRows;
    std::vector<std::vector<std::vector<std::int64_t>>> mPolyhedronRows;

    CellBlock() = default;
    CellBlock(std::string t, NDArray d) : mType(std::move(t)), mData(std::move(d)) {}

    /**
     * @brief Whether this block uses one of the ragged representations.
     * @return `true` iff `mPolygonRows` or `mPolyhedronRows` is non-empty.
     */
    bool IsRagged() const { return !mPolygonRows.empty() || !mPolyhedronRows.empty(); }

    /**
     * @brief Number of cells in this block, whichever representation is active.
     * @return `mPolygonRows.size()`, else `mPolyhedronRows.size()`, else the
     *         first dimension of `mData` (0 if `mData` has no shape).
     */
    std::size_t NumCells() const {
        if (!mPolygonRows.empty())
            return mPolygonRows.size();
        if (!mPolyhedronRows.empty())
            return mPolyhedronRows.size();
        return mData.Shape().empty() ? 0 : mData.Shape()[0];
    }
};

/**
 * @brief The C++ in-memory mesh: points, cell blocks, and field data.
 *
 * Produced by every C++ format reader and consumed by every C++ format
 * writer; see the file-level comment for how this maps to/from the
 * pure-Python `meshio.Mesh` at the pybind11 boundary. Note what is
 * deliberately absent from this struct: `mesh.info`, `point_sets`, and
 * `cell_sets` are Python-only attributes not represented here (they travel,
 * when needed, through a per-format side-channel struct instead).
 */
struct Mesh {
    NDArray mPoints;  // (num_points, dim)
    std::vector<CellBlock> mCells;

    // Field data. mCellData holds one NDArray per cell block, in mCells order.
    // These are unordered_map for O(1) name lookup; where key *order* is
    // observable (Python dict order, on-disk field order) call
    // detail::sorted_keys (map_order.hpp) at the consumption site.
    std::unordered_map<std::string, NDArray> mPointData;
    std::unordered_map<std::string, std::vector<NDArray>> mCellData;
    std::unordered_map<std::string, NDArray> mFieldData;

    /**
     * @brief Number of points in the mesh.
     * @return The first dimension of `mPoints.Shape()`, or 0 if unset.
     */
    std::size_t NumPoints() const { return mPoints.Shape().empty() ? 0 : mPoints.Shape()[0]; }

    // -----------------------------------------------------------------
    // Uniform format-facing API (the compile-time contract shared by all
    // mesh backends — see mesh_api.hpp). Format code must go through these
    // methods, never the public members above; on this backend every method
    // is a trivial inline forward, so there is zero cost over direct access.
    // -----------------------------------------------------------------

    /**
     * @brief Cheap, copyable view over one cell block (see `mesh_api.hpp`).
     *
     * On this backend it simply wraps a `const CellBlock*`; it stays valid
     * only while the underlying `Mesh` is alive and its `mCells` vector is
     * not resized.
     */
    class CellView {
    public:
        explicit CellView(const CellBlock& rBlock) : mpBlock(&rBlock) {}
        /** @brief The meshio cell-type name (e.g. `"triangle"`). */
        const std::string& Type() const { return mpBlock->mType; }
        /** @brief Number of cells in the block (any representation). */
        std::size_t NumCells() const { return mpBlock->NumCells(); }
        /** @brief Nodes per cell for rectangular blocks; 0 for ragged ones. */
        std::size_t NodesPerCell() const {
            return mpBlock->mData.Ndim() >= 2 ? mpBlock->mData.Shape()[1] : 0;
        }
        /** @brief Whether the block uses a ragged representation. */
        bool IsRagged() const { return mpBlock->IsRagged(); }
        /** @brief Whether the block is 2-level ragged (list of faces per cell). */
        bool IsPolyhedron() const { return !mpBlock->mPolyhedronRows.empty(); }
        /** @brief Rectangular `(num_cells, nodes_per_cell)` connectivity (empty if ragged). */
        const NDArray& Conn() const { return mpBlock->mData; }
        /** @brief Node count of polygon cell @p cell (1-level ragged blocks). */
        std::size_t RowSize(std::size_t cell) const { return mpBlock->mPolygonRows[cell].size(); }
        /** @brief Node ids of polygon cell @p cell (1-level ragged blocks). */
        const std::int64_t* Row(std::size_t cell) const {
            return mpBlock->mPolygonRows[cell].data();
        }
        /** @brief Face count of polyhedron cell @p cell (2-level ragged blocks). */
        std::size_t NumFaces(std::size_t cell) const {
            return mpBlock->mPolyhedronRows[cell].size();
        }
        /** @brief `{node ids, count}` of face @p face of polyhedron cell @p cell. */
        std::pair<const std::int64_t*, std::size_t> Face(std::size_t cell, std::size_t face) const {
            const auto& r_face = mpBlock->mPolyhedronRows[cell][face];
            return {r_face.data(), r_face.size()};
        }

    private:
        const CellBlock* mpBlock;
    };

    // --- reader-side ingestion ---

    /** @brief Takes ownership of the point array (float dtype, shape `(n, dim)`). */
    void AssignPoints(NDArray points) { mPoints = std::move(points); }
    /** @brief Appends a rectangular cell block (integer dtype, shape `(n, npc)`). */
    void AddCellBlock(std::string type, NDArray conn) {
        mCells.emplace_back(std::move(type), std::move(conn));
    }
    /** @brief Appends a 1-level ragged (polygon) cell block. */
    void AddPolygonBlock(std::string type, std::vector<std::vector<std::int64_t>> rows) {
        CellBlock cb;
        cb.mType = std::move(type);
        cb.mPolygonRows = std::move(rows);
        mCells.push_back(std::move(cb));
    }
    /** @brief Appends a 2-level ragged (polyhedron) cell block. */
    void AddPolyhedronBlock(std::string type,
                            std::vector<std::vector<std::vector<std::int64_t>>> cells) {
        CellBlock cb;
        cb.mType = std::move(type);
        cb.mPolyhedronRows = std::move(cells);
        mCells.push_back(std::move(cb));
    }
    /** @brief Inserts or replaces a named per-point data array. */
    void AddPointData(std::string name, NDArray data) {
        mPointData[std::move(name)] = std::move(data);
    }
    /** @brief Inserts or replaces a named per-cell data array list (one per block). */
    void AddCellData(std::string name, std::vector<NDArray> blocks) {
        mCellData[std::move(name)] = std::move(blocks);
    }
    /** @brief Appends one block's array to a named cell-data list (creating it if new). */
    void AppendCellData(const std::string& rName, NDArray block) {
        mCellData[rName].push_back(std::move(block));
    }
    /** @brief Inserts or replaces a named field-data array. */
    void AddFieldData(std::string name, NDArray data) {
        mFieldData[std::move(name)] = std::move(data);
    }

    // --- writer-side accessors ---

    /** @brief Spatial dimension of the points (second shape entry), or 0 if unset. */
    std::size_t PointDim() const { return mPoints.Ndim() >= 2 ? mPoints.Shape()[1] : 0; }
    /** @brief The `(num_points, dim)` point array. */
    const NDArray& Points() const { return mPoints; }
    /** @brief Number of cell blocks. */
    std::size_t NumCellBlocks() const { return mCells.size(); }
    /** @brief View over cell block @p i (in insertion order). */
    CellView Cells(std::size_t i) const { return CellView(mCells[i]); }
    /** @brief Range over all cell blocks: `for (const auto cb : mesh.CellRange())`. */
    detail::CellBlockRange<Mesh> CellRange() const { return detail::CellBlockRange<Mesh>(*this); }

    /** @brief Point-data names in sorted order (drives on-disk field order). */
    std::vector<std::string> PointDataNames() const { return detail::sorted_keys(mPointData); }
    /** @brief Number of named point-data arrays. */
    std::size_t NumPointData() const { return mPointData.size(); }
    /** @brief Whether a point-data array named @p rName exists. */
    bool HasPointData(const std::string& rName) const { return mPointData.count(rName) > 0; }
    /** @brief The point-data array named @p rName (throws if absent). */
    const NDArray& PointData(const std::string& rName) const { return mPointData.at(rName); }

    /** @brief Cell-data names in sorted order (drives on-disk field order). */
    std::vector<std::string> CellDataNames() const { return detail::sorted_keys(mCellData); }
    /** @brief Number of named cell-data array lists. */
    std::size_t NumCellData() const { return mCellData.size(); }
    /** @brief Whether a cell-data list named @p rName exists. */
    bool HasCellData(const std::string& rName) const { return mCellData.count(rName) > 0; }
    /** @brief Block @p block of the cell-data list named @p rName (throws if absent). */
    const NDArray& CellData(const std::string& rName, std::size_t block) const {
        return mCellData.at(rName)[block];
    }
    /** @brief Number of blocks in the cell-data list named @p rName (throws if absent). */
    std::size_t CellDataNumBlocks(const std::string& rName) const {
        return mCellData.at(rName).size();
    }

    /** @brief Field-data names in sorted order (drives on-disk field order). */
    std::vector<std::string> FieldDataNames() const { return detail::sorted_keys(mFieldData); }
    /** @brief Number of named field-data arrays. */
    std::size_t NumFieldData() const { return mFieldData.size(); }
    /** @brief Whether a field-data array named @p rName exists. */
    bool HasFieldData(const std::string& rName) const { return mFieldData.count(rName) > 0; }
    /** @brief The field-data array named @p rName (throws if absent). */
    const NDArray& FieldData(const std::string& rName) const { return mFieldData.at(rName); }
};

}  // namespace meshioplusplus
