#include <array>
#include <cstdint>
#include <cstdio>
#include <fstream>
#include <iterator>
#include <sstream>
#include <string>
#include <vector>

// Project includes

namespace meshioplusplus {

namespace {

// meshio linear type -> (lnv, lne, lnf)
const std::vector<std::pair<std::string, std::array<int, 3>>>& topology() {
    static const std::vector<std::pair<std::string, std::array<int, 3>>> m = {
        {"line", {2, 1, 0}},  {"triangle", {3, 3, 1}},    {"quad", {4, 4, 1}},
        {"tetra", {4, 6, 4}}, {"hexahedron", {8, 12, 6}}, {"wedge", {6, 9, 5}}};
    return m;
}

std::string type_from_dims(int lnv, int lne, int lnf, int lnn) {
    for (const auto& kv : topology())
        if (kv.second[0] == lnv && kv.second[1] == lne && kv.second[2] == lnf &&
            kv.second[0] == lnn)
            return kv.first;
    throw ReadError("MFM: unsupported (non-linear) element");
}

}  // namespace

Mesh read_mfm(const std::string& rPath) {
    std::ifstream in(rPath, std::ios::binary);
    if (!in)
        throw ReadError("Could not open file: " + rPath);

    // First non-empty line: header.
    std::string line;
    std::vector<long long> header;
    while (std::getline(in, line)) {
        std::istringstream iss(line);
        long long v;
        while (iss >> v)
            header.push_back(v);
        if (!header.empty())
            break;
    }
    if (header.size() < 8)
        throw ReadError("MFM: expected a header of 8 integers");
    const long long nel = header[0], nnod = header[1], nver = header[2];
    const int dim = static_cast<int>(header[3]);
    const int lnn = static_cast<int>(header[4]), lnv = static_cast<int>(header[5]);
    const int lne = static_cast<int>(header[6]), lnf = static_cast<int>(header[7]);

    std::string cell_type = type_from_dims(lnv, lne, lnf, lnn);
    if (lnn != lnv || nnod != nver)
        throw ReadError("MFM: only linear (P1) elements are supported");

    // Remaining tokens.
    std::vector<std::string> tok((std::istream_iterator<std::string>(in)),
                                 std::istream_iterator<std::string>());
    std::size_t pos = 0;
    auto need = [&](std::size_t n) {
        if (pos + n > tok.size())
            throw ReadError("MFM: unexpected end of file");
    };

    NDArray data(DType::Int64, {static_cast<std::size_t>(nel), static_cast<std::size_t>(lnv)});
    need(static_cast<std::size_t>(nel) * lnv);
    for (long long i = 0; i < nel * lnv; ++i)
        data.As<std::int64_t>()[i] = std::strtoll(tok[pos++].c_str(), nullptr, 10) - 1;

    // reference arrays (discarded): nrc (dim==3), nra (dim>=2), nrv
    if (dim == 3) {
        need(static_cast<std::size_t>(nel) * lnf);
        pos += nel * lnf;
    }
    if (dim >= 2) {
        need(static_cast<std::size_t>(nel) * lne);
        pos += nel * lne;
    }
    need(static_cast<std::size_t>(nel) * lnv);
    pos += nel * lnv;

    Mesh mesh;
    NDArray pts(DType::Float64, {static_cast<std::size_t>(nver), static_cast<std::size_t>(dim)});
    need(static_cast<std::size_t>(nver) * dim);
    for (long long i = 0; i < nver * dim; ++i)
        pts.As<double>()[i] = std::strtod(tok[pos++].c_str(), nullptr);
    mesh.AssignPoints(std::move(pts));

    NDArray ref(DType::Int64, {static_cast<std::size_t>(nel)});
    need(static_cast<std::size_t>(nel));
    for (long long i = 0; i < nel; ++i)
        ref.As<std::int64_t>()[i] = std::strtoll(tok[pos++].c_str(), nullptr, 10);

    mesh.AddCellBlock(cell_type, std::move(data));
    std::vector<NDArray> refs;
    refs.push_back(std::move(ref));
    mesh.AddCellData("mfm:ref", std::move(refs));
    return mesh;
}

void write_mfm(const std::string& rPath, const Mesh& rMesh, const std::string& rFloatFmt) {
    // Single element type only.
    std::string cell_type;
    for (const auto cb : rMesh.CellRange()) {
        if (cell_type.empty())
            cell_type = cb.Type();
        else if (cb.Type() != cell_type)
            throw WriteError("MFM can only write a single element type");
    }
    if (cell_type.empty())
        throw WriteError("MFM: empty mesh");

    const std::array<int, 3>* topo = nullptr;
    for (const auto& kv : topology())
        if (kv.first == cell_type) {
            topo = &kv.second;
            break;
        }
    if (!topo)
        throw WriteError("MFM does not support '" + cell_type + "' cells");
    const int lnv = (*topo)[0], lne = (*topo)[1], lnf = (*topo)[2], lnn = lnv;

    std::size_t nel = 0;
    for (const auto cb : rMesh.CellRange())
        nel += cb.NumCells();
    const std::size_t nver = rMesh.NumPoints();
    const int dim = static_cast<int>(rMesh.PointDim());

    // subdomain
    std::vector<std::int64_t> nsd(nel, 1);
    if (rMesh.HasCellData("mfm:ref")) {
        std::size_t p = 0;
        for (std::size_t b = 0; b < rMesh.CellDataNumBlocks("mfm:ref"); ++b) {
            const NDArray& blk = rMesh.CellData("mfm:ref", b);
            for (std::size_t i = 0; i < blk.Size() && p < nel; ++i)
                nsd[p++] = detail::read_int(blk, i);
        }
    }

    std::ofstream f(rPath, std::ios::binary);
    if (!f)
        throw WriteError("Could not open file for writing: " + rPath);
    f << nel << " " << nver << " " << nver << " " << dim << " " << lnn << " " << lnv << " " << lne
      << " " << lnf << "\n";

    // connectivity (1-based)
    for (const auto cb : rMesh.CellRange()) {
        const NDArray& conn = cb.Conn();
        std::size_t n = cb.NumCells();
        std::size_t k = detail::cols(conn);
        for (std::size_t r = 0; r < n; ++r) {
            for (std::size_t j = 0; j < k; ++j)
                f << (detail::read_int(conn, r * k + j) + 1) << (j + 1 == k ? '\n' : ' ');
        }
    }
    // zero reference arrays
    auto zeros = [&](int cols) {
        for (std::size_t r = 0; r < nel; ++r)
            for (int j = 0; j < cols; ++j)
                f << 0 << (j + 1 == cols ? '\n' : ' ');
    };
    if (dim == 3)
        zeros(lnf);
    if (dim >= 2)
        zeros(lne);
    zeros(lnv);
    // coordinates
    const NDArray& points = rMesh.Points();
    std::string fmt = "%" + rFloatFmt;
    char buf[64];
    for (std::size_t i = 0; i < nver; ++i)
        for (int c = 0; c < dim; ++c) {
            std::snprintf(buf, sizeof(buf), fmt.c_str(),
                          detail::read_double(points, i * dim + c));
            f << buf << (c + 1 == dim ? '\n' : ' ');
        }
    // subdomain
    for (std::size_t i = 0; i < nel; ++i)
        f << nsd[i] << "\n";
}

}  // namespace meshioplusplus
// ===== end cpp/src/formats/mfm.cpp =====
// ===== begin cpp/src/formats/mphtxt.cpp =====
#include <cstdint>
#include <cstdio>
#include <fstream>
#include <sstream>
#include <string>
#include <unordered_map>
#include <vector>

// Project includes

namespace meshioplusplus {

namespace {

std::string comsol_to_meshio(const std::string& rT) {
    static const std::unordered_map<std::string, std::string> m = {
        {"vtx", "vertex"},     {"edg", "line"},         {"tri", "triangle"}, {"quad", "quad"},
        {"tet", "tetra"},      {"prism", "wedge"},      {"pyr", "pyramid"},  {"hex", "hexahedron"},
        {"edg2", "line3"},     {"tri2", "triangle6"},   {"quad2", "quad9"},  {"tet2", "tetra10"},
        {"prism2", "wedge18"}, {"hex2", "hexahedron27"}};
    auto it = m.find(rT);
    return it == m.end() ? std::string() : it->second;
}

std::string meshio_to_comsol(const std::string& rT) {
    static const std::unordered_map<std::string, std::string> m = {
        {"vertex", "vtx"},     {"line", "edg"},         {"triangle", "tri"}, {"quad", "quad"},
        {"tetra", "tet"},      {"wedge", "prism"},      {"pyramid", "pyr"},  {"hexahedron", "hex"},
        {"line3", "edg2"},     {"triangle6", "tri2"},   {"quad9", "quad2"},  {"tetra10", "tet2"},
        {"wedge18", "prism2"}, {"hexahedron27", "hex2"}};
    auto it = m.find(rT);
    return it == m.end() ? std::string() : it->second;
}

const std::vector<int>* perm_of(const std::string& rT) {
    static const std::unordered_map<std::string, std::vector<int>> m = {
        {"quad", {0, 1, 3, 2}}, {"hexahedron", {0, 1, 3, 2, 4, 5, 7, 6}}};
    auto it = m.find(rT);
    return it == m.end() ? nullptr : &it->second;
}

struct MphtxtCursor {
    std::vector<std::string> mT;
    std::size_t mI = 0;
    const std::string& Tok() {
        if (mI >= mT.size())
            throw ReadError("mphtxt: unexpected end of file");
        return mT[mI++];
    }
    long long Integer() { return std::strtoll(Tok().c_str(), nullptr, 10); }
    double Real() { return std::strtod(Tok().c_str(), nullptr); }
    std::string Str() {
        Integer();  // length prefix
        return Tok();
    }
};

}  // namespace

Mesh read_mphtxt(const std::string& rPath) {
    std::ifstream in(rPath, std::ios::binary);
    if (!in)
        throw ReadError("Could not open file: " + rPath);
    MphtxtCursor c;
    std::string line;
    while (std::getline(in, line)) {
        std::size_t h = line.find('#');
        if (h != std::string::npos)
            line = line.substr(0, h);
        std::istringstream iss(line);
        std::string w;
        while (iss >> w)
            c.mT.push_back(w);
    }

    c.Integer();  // version major
    c.Integer();  // version minor
    for (long long k = c.Integer(); k > 0; --k)
        c.Str();  // tags
    const long long n_types = c.Integer();
    for (long long k = 0; k < n_types; ++k)
        c.Str();  // type names

    Mesh mesh;
    std::vector<NDArray> geom;

    for (long long obj = 0; obj < n_types; ++obj) {
        c.Integer();
        c.Integer();
        c.Integer();  // object type indices
        c.Str();      // class name
        c.Integer();  // object version
        const long long sdim = c.Integer();
        const long long n_points = c.Integer();
        const long long lowest = c.Integer();
        NDArray pts(DType::Float64,
                    {static_cast<std::size_t>(n_points), static_cast<std::size_t>(sdim)});
        for (long long p = 0; p < n_points * sdim; ++p)
            pts.As<double>()[p] = c.Real();
        mesh.AssignPoints(std::move(pts));

        const long long n_eltypes = c.Integer();
        for (long long e = 0; e < n_eltypes; ++e) {
            std::string ctype = c.Str();
            std::string mtype = comsol_to_meshio(ctype);
            if (mtype.empty())
                throw ReadError("mphtxt: unknown element type " + ctype);
            const long long nn = c.Integer();
            const long long ne = c.Integer();
            NDArray conn(DType::Int64,
                         {static_cast<std::size_t>(ne), static_cast<std::size_t>(nn)});
            std::vector<std::int64_t> raw(ne * nn);
            for (long long v = 0; v < ne * nn; ++v)
                raw[v] = c.Integer() - lowest;
            const std::vector<int>* p = perm_of(mtype);
            for (long long r = 0; r < ne; ++r)
                for (long long j = 0; j < nn; ++j)
                    conn.As<std::int64_t>()[r * nn + j] =
                        p ? raw[r * nn + (*p)[j]] : raw[r * nn + j];

            const long long npar_per = c.Integer();
            const long long npar = c.Integer();
            for (long long v = 0; v < npar * npar_per; ++v)
                c.Tok();
            const long long ngeom = c.Integer();
            NDArray g(DType::Int64, {static_cast<std::size_t>(ngeom)});
            for (long long v = 0; v < ngeom; ++v)
                g.As<std::int64_t>()[v] = c.Integer();
            const long long nud = c.Integer();
            for (long long v = 0; v < nud * 2; ++v)
                c.Integer();

            mesh.AddCellBlock(mtype, std::move(conn));
            geom.push_back(std::move(g));
        }
        break;  // first mesh object only
    }

    if (!geom.empty())
        mesh.AddCellData("mphtxt:geom", std::move(geom));
    return mesh;
}

void write_mphtxt(const std::string& rPath, const Mesh& rMesh) {
    std::ofstream f(rPath, std::ios::binary);
    if (!f)
        throw WriteError("Could not open file for writing: " + rPath);

    const std::size_t sdim = rMesh.PointDim();

    struct Blk {
        std::size_t mIdx;
        Mesh::CellView mCb;
    };
    std::vector<Blk> blocks;
    for (std::size_t k = 0; k < rMesh.NumCellBlocks(); ++k) {
        const auto cb = rMesh.Cells(k);
        if (!meshio_to_comsol(cb.Type()).empty())
            blocks.push_back({k, cb});
        else
            throw WriteError("mphtxt: unsupported cell type " + cb.Type());
    }

    const bool has_geom = rMesh.HasCellData("mphtxt:geom");

    f << "# Created by meshio++ (C++ core)\n\n";
    f << "0 1\n";
    f << "1 # number of tags\n5 mesh1\n";
    f << "1 # number of types\n3 obj\n\n";
    f << "0 0 1\n4 Mesh # class\n2 # version\n";
    f << sdim << " # sdim\n";
    f << rMesh.NumPoints() << " # number of mesh points\n";
    f << "1 # lowest mesh point index\n\n# Mesh point coordinates\n";
    const NDArray& points = rMesh.Points();
    char buf[32];
    for (std::size_t i = 0; i < rMesh.NumPoints(); ++i) {
        for (std::size_t cc = 0; cc < sdim; ++cc) {
            std::snprintf(buf, sizeof(buf), "%.16g", detail::read_double(points, i * sdim + cc));
            f << buf << (cc + 1 == sdim ? '\n' : ' ');
        }
    }
    f << "\n" << blocks.size() << " # number of element types\n\n";

    int ti = 0;
    for (const auto& b : blocks) {
        const auto cb = b.mCb;
        std::string ctype = meshio_to_comsol(cb.Type());
        const std::vector<int>* p = perm_of(cb.Type());
        const NDArray& conn = cb.Conn();
        std::size_t nn = detail::cols(conn);
        std::size_t ne = cb.NumCells();
        f << "# Type #" << (++ti) << "\n\n";
        f << ctype.size() << " " << ctype << " # type name\n\n";
        f << nn << " # number of nodes per element\n";
        f << ne << " # number of elements\n# Elements\n";
        for (std::size_t r = 0; r < ne; ++r) {
            for (std::size_t j = 0; j < nn; ++j) {
                std::size_t src = p ? (*p)[j] : j;
                f << (detail::read_int(conn, r * nn + src) + 1) << (j + 1 == nn ? '\n' : ' ');
            }
        }
        f << "\n" << nn << " # number of parameter values per element\n";
        f << "0 # number of parameters\n# Parameters\n\n";
        f << ne << " # number of geometric entity indices\n# Geometric entity indices\n";
        const NDArray* g = (has_geom && b.mIdx < rMesh.CellDataNumBlocks("mphtxt:geom"))
                               ? &rMesh.CellData("mphtxt:geom", b.mIdx)
                               : nullptr;
        for (std::size_t r = 0; r < ne; ++r)
            f << (g ? detail::read_int(*g, r) : 0) << "\n";
        f << "\n0 # number of up/down pairs\n# Up/down\n\n";
    }
}

}  // namespace meshioplusplus
