// ===== begin cpp/src/formats/vtk_read.cpp =====
#include <cctype>
#include <cstdint>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <sstream>
#include <string>
#include <unordered_map>
#include <vector>

// Project includes

namespace meshioplusplus {

namespace {

DType dtype_from_vtk_token(std::string t) {
    for (auto& ch : t)
        ch = static_cast<char>(std::tolower(static_cast<unsigned char>(ch)));
    if (t == "float")
        return DType::Float32;
    if (t == "double")
        return DType::Float64;
    if (t == "int" || t == "vtktypeint64" || t == "long")
        return DType::Int64;
    if (t == "vtktypeint8" || t == "char")
        return DType::Int8;
    if (t == "vtktypeint16" || t == "short")
        return DType::Int16;
    if (t == "vtktypeint32")
        return DType::Int32;
    if (t == "vtktypeuint8" || t == "unsigned_char")
        return DType::UInt8;
    if (t == "vtktypeuint16")
        return DType::UInt16;
    if (t == "vtktypeuint32")
        return DType::UInt32;
    if (t == "vtktypeuint64")
        return DType::UInt64;
    throw ReadError("VTK data type '" + t + "' not supported by the C++ reader");
}

void store(NDArray& rA, std::size_t i, double d, std::int64_t v) {
    switch (rA.Dtype()) {
        case DType::Float32:
            rA.As<float>()[i] = static_cast<float>(d);
            break;
        case DType::Float64:
            rA.As<double>()[i] = d;
            break;
        case DType::Int8:
            rA.As<std::int8_t>()[i] = static_cast<std::int8_t>(v);
            break;
        case DType::Int16:
            rA.As<std::int16_t>()[i] = static_cast<std::int16_t>(v);
            break;
        case DType::Int32:
            rA.As<std::int32_t>()[i] = static_cast<std::int32_t>(v);
            break;
        case DType::Int64:
            rA.As<std::int64_t>()[i] = v;
            break;
        case DType::UInt8:
            rA.As<std::uint8_t>()[i] = static_cast<std::uint8_t>(v);
            break;
        case DType::UInt16:
            rA.As<std::uint16_t>()[i] = static_cast<std::uint16_t>(v);
            break;
        case DType::UInt32:
            rA.As<std::uint32_t>()[i] = static_cast<std::uint32_t>(v);
            break;
        case DType::UInt64:
            rA.As<std::uint64_t>()[i] = static_cast<std::uint64_t>(v);
            break;
    }
}

struct VtkCursor {
    const std::string& mBuf;
    std::size_t mPos = 0;

    explicit VtkCursor(const std::string& rB) : mBuf(rB) {}

    bool Eof() const { return mPos >= mBuf.size(); }

    std::string ReadLine() {
        std::size_t start = mPos;
        while (mPos < mBuf.size() && mBuf[mPos] != '\n')
            ++mPos;
        std::string line = mBuf.substr(start, mPos - start);
        if (mPos < mBuf.size())
            ++mPos;  // skip '\n'
        if (!line.empty() && line.back() == '\r')
            line.pop_back();
        return line;
    }

    void ConsumeEol() {
        while (mPos < mBuf.size() && mBuf[mPos] != '\n' &&
               std::isspace(static_cast<unsigned char>(mBuf[mPos])))
            ++mPos;
        if (mPos < mBuf.size() && mBuf[mPos] == '\n')
            ++mPos;
    }

    // Read `count` values of dtype `dt`, ascii or big-endian binary.
    NDArray ReadValues(DType dt, std::size_t count, bool is_ascii) {
        NDArray a = NDArray::Uninit(dt, {count});  // every element written below
        const std::size_t isz = dtype_size(dt);
        if (is_ascii) {
            const bool flt = detail::is_float_dtype(dt);
            const char* base = mBuf.c_str();
            for (std::size_t i = 0; i < count; ++i) {
                char* endp = nullptr;
                if (flt) {
                    double x = std::strtod(base + mPos, &endp);
                    if (endp == base + mPos)
                        throw ReadError("VTK ascii parse error");
                    store(a, i, x, 0);
                } else {
                    long long x = std::strtoll(base + mPos, &endp, 10);
                    if (endp == base + mPos)
                        throw ReadError("VTK ascii parse error");
                    store(a, i, 0.0, static_cast<std::int64_t>(x));
                }
                mPos = static_cast<std::size_t>(endp - base);
            }
        } else {
            if (mPos + count * isz > mBuf.size())
                throw ReadError("VTK binary truncated");
            char* out = reinterpret_cast<char*>(a.Data());
            // Element offsets are i*isz -> byte-swap in parallel (bswap intrinsic).
            const char* src = mBuf.data() + mPos;
            const int w = static_cast<int>(isz);
            parallel_for_bw(
                count, [&](std::size_t i) { detail::bswap_copy(out + i * isz, src + i * isz, w); });
            mPos += count * isz;
        }
        ConsumeEol();
        return a;
    }
};

std::vector<std::string> split(const std::string& rS) {
    std::vector<std::string> out;
    std::istringstream iss(rS);
    std::string tok;
    while (iss >> tok)
        out.push_back(tok);
    return out;
}

std::string vtk_upper(std::string s) {
    for (auto& c : s)
        c = static_cast<char>(std::toupper(static_cast<unsigned char>(c)));
    return s;
}

std::vector<std::int64_t> vtk_to_int64(const NDArray& rA) {
    std::vector<std::int64_t> v(rA.Size());
    std::int64_t* dst = v.data();
    // Hoist the per-element dtype switch out of the loop, then bulk-convert.
    detail::dispatch_dtype(rA.Dtype(), [&]<class T>() {
        const T* src = rA.As<T>();
        parallel_for_bw(rA.Size(),
                        [&](std::size_t i) { dst[i] = static_cast<std::int64_t>(src[i]); });
    });
    return v;
}

}  // namespace

Mesh read_vtk(const std::string& rPath) {
    std::ifstream in(rPath, std::ios::binary);
    if (!in)
        throw ReadError("Could not open file: " + rPath);
    // Bulk slurp (seek+read) rather than char-by-char istreambuf_iterator.
    in.seekg(0, std::ios::end);
    std::streamoff len = in.tellg();
    in.seekg(0, std::ios::beg);
    std::string buf;
    if (len > 0) {
        buf.resize(static_cast<std::size_t>(len));
        in.read(buf.data(), len);
    }
    VtkCursor cur(buf);

    std::string header = cur.ReadLine();
    const bool is_v5 = header.find("Version 5") != std::string::npos;
    cur.ReadLine();  // title
    std::string dtype_line = vtk_upper(cur.ReadLine());
    bool is_ascii;
    if (dtype_line.find("ASCII") != std::string::npos)
        is_ascii = true;
    else if (dtype_line.find("BINARY") != std::string::npos)
        is_ascii = false;
    else
        throw ReadError("Unknown VTK data type line: " + dtype_line);

    Mesh mesh;
    std::vector<std::int64_t> conn, offsets, types;
    // Held alive so reconstruct_cells can read the int64 connectivity buffer
    // directly (VTK 5.1), skipping a to_int64 copy of the whole connectivity.
    NDArray conn_nd;
    const std::int64_t* conn_ptr = nullptr;
    bool conn_owned = false;  // conn_nd owns the int64 connectivity (VTK 5.1)
    std::unordered_map<std::string, NDArray> cell_data_raw;
    std::string active;  // POINT_DATA or CELL_DATA

    while (!cur.Eof()) {
        std::string line = cur.ReadLine();
        if (line.empty())
            continue;
        std::vector<std::string> tok = split(line);
        if (tok.empty())
            continue;
        std::string section = vtk_upper(tok[0]);

        if (section == "DATASET") {
            if (tok.size() < 2 || vtk_upper(tok[1]) != "UNSTRUCTURED_GRID")
                throw ReadError("C++ VTK reader only handles UNSTRUCTURED_GRID");
        } else if (section == "POINTS") {
            std::size_t n = std::stoull(tok[1]);
            DType dt = dtype_from_vtk_token(tok[2]);
            NDArray pts = cur.ReadValues(dt, n * 3, is_ascii);
            pts.Reshape({n, 3});
            mesh.AssignPoints(std::move(pts));
        } else if (section == "CELLS") {
            if (is_v5) {
                std::size_t num_off = std::stoull(tok[1]);
                std::size_t num_idx = std::stoull(tok[2]);
                std::string l = cur.ReadLine();
                if (vtk_upper(l).rfind("OFFSETS", 0) != 0)
                    throw ReadError("Expected OFFSETS (VTK 5.1 layout)");
                DType odt = dtype_from_vtk_token(split(l)[1]);
                std::vector<std::int64_t> off_all =
                    vtk_to_int64(cur.ReadValues(odt, num_off, is_ascii));
                l = cur.ReadLine();
                if (vtk_upper(l).rfind("CONNECTIVITY", 0) != 0)
                    throw ReadError("Expected CONNECTIVITY");
                DType cdt = dtype_from_vtk_token(split(l)[1]);
                conn_nd = cur.ReadValues(cdt, num_idx, is_ascii);
                if (conn_nd.Dtype() == DType::Int64) {
                    // Already int64 (vtktypeint64) -> read the buffer directly.
                    conn_ptr = conn_nd.As<std::int64_t>();
                    conn_owned = true;
                } else {
                    conn = vtk_to_int64(conn_nd);
                    conn_ptr = conn.data();
                }
                // off_all has a leading 0; end-offsets are the remainder.
                offsets.assign(off_all.begin() + 1, off_all.end());
            } else {
                // Version 4.2: interleaved [count, nodes...]; int32 values.
                std::size_t num_cells = std::stoull(tok[1]);
                std::size_t total = std::stoull(tok[2]);
                DType dt = is_ascii ? DType::Int64 : DType::Int32;
                std::vector<std::int64_t> raw = vtk_to_int64(cur.ReadValues(dt, total, is_ascii));
                conn.reserve(total - num_cells);
                offsets.reserve(num_cells);
                std::size_t p = 0;
                std::int64_t running = 0;
                for (std::size_t i = 0; i < num_cells; ++i) {
                    std::int64_t n = raw[p++];
                    for (std::int64_t j = 0; j < n; ++j)
                        conn.push_back(raw[p++]);
                    running += n;
                    offsets.push_back(running);
                }
                conn_ptr = conn.data();
            }
        } else if (section == "CELL_TYPES") {
            std::size_t n = std::stoull(tok[1]);
            DType dt = is_ascii ? DType::Int64 : DType::Int32;
            types = vtk_to_int64(cur.ReadValues(dt, n, is_ascii));
        } else if (section == "POINT_DATA") {
            active = "POINT_DATA";
        } else if (section == "CELL_DATA") {
            active = "CELL_DATA";
        } else if (section == "FIELD") {
            std::size_t k = std::stoull(tok[2]);
            for (std::size_t fi = 0; fi < k; ++fi) {
                std::vector<std::string> ft = split(cur.ReadLine());
                if (!ft.empty() && vtk_upper(ft[0]) == "METADATA") {
                    while (true) {
                        std::string ml = cur.ReadLine();
                        bool blank = true;
                        for (char c : ml)
                            if (!std::isspace(static_cast<unsigned char>(c)))
                                blank = false;
                        if (blank)
                            break;
                    }
                    ft = split(cur.ReadLine());
                }
                std::string name = ft[0];
                std::size_t ncomp = std::stoull(ft[1]);
                std::size_t ntuples = std::stoull(ft[2]);
                DType dt = dtype_from_vtk_token(ft[3]);
                NDArray arr = cur.ReadValues(dt, ncomp * ntuples, is_ascii);
                if (ncomp != 1)
                    arr.Reshape({ntuples, ncomp});
                if (active == "POINT_DATA")
                    mesh.AddPointData(name, std::move(arr));
                else
                    cell_data_raw.emplace(name, std::move(arr));
            }
        } else if (section == "METADATA") {
            while (true) {
                std::string ml = cur.ReadLine();
                bool blank = true;
                for (char c : ml)
                    if (!std::isspace(static_cast<unsigned char>(c)))
                        blank = false;
                if (blank || cur.Eof())
                    break;
            }
        } else {
            throw ReadError("VTK section '" + section + "' not supported by the C++ reader");
        }
    }

    // Fast path (zero copy): a single cell type spanning all cells, non-special,
    // with an identity VTK->meshio node order and regular end-offsets
    // (offsets[i] == (i+1)*n) means the owning int64 connectivity NDArray is
    // already the block data -> reshape and move it straight into the cell block
    // instead of gathering a fresh copy.
    bool moved = false;
    if (conn_owned && !types.empty()) {
        const int vt = static_cast<int>(types[0]);
        bool single = true;
        for (std::size_t i = 1; i < types.size(); ++i)
            if (types[i] != types[0]) {
                single = false;
                break;
            }
        const auto& tmap = vtk_to_meshio_type();
        auto it = tmap.find(vt);
        if (single && it != tmap.end() && !is_special_cell(it->second) &&
            vtk_to_meshio_order(vt).empty()) {
            auto nit = num_nodes_per_cell().find(it->second);
            if (nit != num_nodes_per_cell().end()) {
                const std::size_t n = static_cast<std::size_t>(nit->second);
                const std::size_t ncells = types.size();
                bool regular = conn_nd.Size() == ncells * n && offsets.size() == ncells;
                for (std::size_t i = 0; regular && i < ncells; ++i)
                    if (offsets[i] != static_cast<std::int64_t>((i + 1) * n))
                        regular = false;
                if (regular) {
                    conn_nd.Reshape({ncells, n});
                    mesh.AddCellBlock(it->second, std::move(conn_nd));
                    for (auto& kv : cell_data_raw)
                        mesh.AppendCellData(kv.first, std::move(kv.second));
                    moved = true;
                }
            }
        }
    }
    if (!moved)
        detail::reconstruct_cells(conn_ptr, offsets, types, cell_data_raw, mesh);
    return mesh;
}

}  // namespace meshioplusplus
// ===== end cpp/src/formats/vtk_read.cpp =====
// ===== begin cpp/src/formats/vtp.cpp =====
#include <cstdint>
#include <cstring>
#include <fstream>
#include <string>
#include <vector>

// Project includes

namespace meshioplusplus {

namespace {

using detail::cols;
using detail::read_double;
using detail::read_int;
using detail::vtu_ascii_double;
using detail::vtu_ascii_ndarray;
using detail::vtu_type_str;

// PolyData section a cell block belongs to (VTK's canonical cell order).
enum class VtpSection { Verts = 0, Lines = 1, Polys = 2 };

VtpSection vtp_section_of(const Mesh::CellView& rCb) {
    const std::string& type = rCb.Type();
    if (rCb.IsPolyhedron())
        throw WriteError("VTP: PolyData cannot hold polyhedron cells");
    if (type == "vertex")
        return VtpSection::Verts;
    if (type == "line")
        return VtpSection::Lines;
    if (type == "triangle" || type == "quad" || type == "polygon")
        return VtpSection::Polys;
    throw WriteError("VTP: PolyData cannot hold '" + type + "' cells");
}

// Flat connectivity + VTK end-offsets of one section's blocks.
struct VtpSectionData {
    std::vector<std::int64_t> mConn;
    std::vector<std::int64_t> mOffsets;
};

void vtp_append_block(VtpSectionData& rSec, const Mesh::CellView& rCb) {
    if (rCb.IsRagged()) {
        for (std::size_t r = 0; r < rCb.NumCells(); ++r) {
            const std::size_t sz = rCb.RowSize(r);
            const std::int64_t* row = rCb.Row(r);
            rSec.mConn.insert(rSec.mConn.end(), row, row + sz);
            rSec.mOffsets.push_back(static_cast<std::int64_t>(rSec.mConn.size()));
        }
        return;
    }
    const NDArray& conn = rCb.Conn();
    const std::size_t k = cols(conn);
    for (std::size_t r = 0; r < rCb.NumCells(); ++r) {
        for (std::size_t j = 0; j < k; ++j)
            rSec.mConn.push_back(read_int(conn, r * k + j));
        rSec.mOffsets.push_back(static_cast<std::int64_t>(rSec.mConn.size()));
    }
}

}  // namespace

void write_vtp(const std::string& rPath, const Mesh& rMesh, bool binary, bool zlib) {
    // Classify blocks and build the VTK canonical order (Verts, Lines, Polys)
    // as a stable partition of the mesh's block order.
    const std::size_t nblocks = rMesh.NumCellBlocks();
    std::vector<VtpSection> sections(nblocks);
    for (std::size_t bi = 0; bi < nblocks; ++bi)
        sections[bi] = vtp_section_of(rMesh.Cells(bi));
    std::vector<std::size_t> block_order;
    block_order.reserve(nblocks);
    VtpSectionData verts, lines, polys;
    for (VtpSection want : {VtpSection::Verts, VtpSection::Lines, VtpSection::Polys})
        for (std::size_t bi = 0; bi < nblocks; ++bi) {
            if (sections[bi] != want)
                continue;
            block_order.push_back(bi);
            VtpSectionData& sec = want == VtpSection::Verts   ? verts
                                  : want == VtpSection::Lines ? lines
                                                              : polys;
            vtp_append_block(sec, rMesh.Cells(bi));
        }

    for (std::size_t i = 0; i < verts.mOffsets.size(); ++i)
        if (verts.mOffsets[i] - (i == 0 ? 0 : verts.mOffsets[i - 1]) != 1)
            throw WriteError("VTP: vertex cells must have exactly one node");

    std::ofstream os(rPath, std::ios::binary);
    if (!os)
        throw WriteError("Could not open file for writing: " + rPath);

    const NDArray& points = rMesh.Points();
    const std::size_t num_points = rMesh.NumPoints();
    const std::size_t dim = rMesh.PointDim();
    const std::size_t pt_isz = dtype_size(points.Dtype());

    const char* fmt = binary ? "binary" : "ascii";

    auto da_header = [&](const char* type, const std::string& name, int ncomp) {
        os << "<DataArray type=\"" << type << "\" Name=\"" << name << "\"";
        if (ncomp > 0)
            os << " NumberOfComponents=\"" << ncomp << "\"";
        os << " format=\"" << fmt << "\">\n";
    };
    auto emit_bin = [&](const unsigned char* d, std::size_t n) {
        os << detail::vtu_encode_binary(d, n, zlib) << "\n";
    };
    auto emit_i64 = [&](const char* name, const std::vector<std::int64_t>& v) {
        da_header("Int64", name, 0);
        if (binary) {
            emit_bin(reinterpret_cast<const unsigned char*>(v.data()),
                     v.size() * sizeof(std::int64_t));
        } else {
            for (std::int64_t x : v)
                os << x << '\n';
        }
        os << "</DataArray>\n";
    };

    os << "<?xml version=\"1.0\"?>\n";
    os << "<VTKFile type=\"PolyData\" version=\"0.1\" byte_order=\"LittleEndian\"";
    if (binary && zlib)
        os << " compressor=\"vtkZLibDataCompressor\"";
    os << ">\n";
    os << "<!--This file was created by meshio++ (C++ core)-->\n";
    os << "<PolyData>\n";
    os << "<Piece NumberOfPoints=\"" << num_points << "\" NumberOfVerts=\"" << verts.mOffsets.size()
       << "\" NumberOfLines=\"" << lines.mOffsets.size()
       << "\" NumberOfStrips=\"0\" NumberOfPolys=\"" << polys.mOffsets.size() << "\">\n";

    // Points (3 components; pad 2D with zero z) — same layout as the VTU writer.
    os << "<Points>\n";
    da_header(vtu_type_str(points.Dtype()), "Points", 3);
    if (binary) {
        std::vector<unsigned char> buf(num_points * 3 * pt_isz, 0);
        const auto* src = reinterpret_cast<const unsigned char*>(points.Data());
        parallel_for(num_points, [&](std::size_t r) {
            for (std::size_t c = 0; c < dim && c < 3; ++c)
                std::memcpy(buf.data() + (r * 3 + c) * pt_isz, src + (r * dim + c) * pt_isz,
                            pt_isz);
        });
        emit_bin(buf.data(), buf.size());
    } else {
        for (std::size_t r = 0; r < num_points; ++r)
            for (std::size_t c = 0; c < 3; ++c)
                vtu_ascii_double(os, (c < dim) ? read_double(points, r * dim + c) : 0.0);
    }
    os << "</DataArray>\n</Points>\n";

    auto emit_section = [&](const char* tag, const VtpSectionData& rSec) {
        if (rSec.mOffsets.empty())
            return;
        os << "<" << tag << ">\n";
        emit_i64("connectivity", rSec.mConn);
        emit_i64("offsets", rSec.mOffsets);
        os << "</" << tag << ">\n";
    };
    emit_section("Verts", verts);
    emit_section("Lines", lines);
    emit_section("Polys", polys);

    if (rMesh.NumPointData() != 0) {
        os << "<PointData>\n";
        for (const auto& name : rMesh.PointDataNames()) {
            const NDArray& d = rMesh.PointData(name);
            int ncomp = (d.Shape().size() == 2) ? static_cast<int>(cols(d)) : 0;
            da_header(vtu_type_str(d.Dtype()), name, ncomp);
            if (binary)
                emit_bin(reinterpret_cast<const unsigned char*>(d.Data()), d.Nbytes());
            else
                vtu_ascii_ndarray(os, d);
            os << "</DataArray>\n";
        }
        os << "</PointData>\n";
    }

    if (rMesh.NumCellData() != 0) {
        // Cell data follows the reordered (Verts, Lines, Polys) block order.
        os << "<CellData>\n";
        for (const auto& name : rMesh.CellDataNames()) {
            const std::size_t ndblocks = rMesh.CellDataNumBlocks(name);
            if (ndblocks == 0)
                continue;
            const NDArray& first = rMesh.CellData(name, 0);
            int ncomp = (first.Shape().size() == 2) ? static_cast<int>(cols(first)) : 0;
            da_header(vtu_type_str(first.Dtype()), name, ncomp);
            if (binary) {
                std::vector<unsigned char> buf;
                for (std::size_t bi : block_order) {
                    if (bi >= ndblocks)
                        continue;
                    const NDArray& blk = rMesh.CellData(name, bi);
                    const unsigned char* p = reinterpret_cast<const unsigned char*>(blk.Data());
                    buf.insert(buf.end(), p, p + blk.Nbytes());
                }
                emit_bin(buf.data(), buf.size());
            } else {
                for (std::size_t bi : block_order) {
                    if (bi >= ndblocks)
                        continue;
                    vtu_ascii_ndarray(os, rMesh.CellData(name, bi));
                }
            }
            os << "</DataArray>\n";
        }
        os << "</CellData>\n";
    }

    os << "</Piece>\n</PolyData>\n</VTKFile>\n";
}

}  // namespace meshioplusplus
// ===== end cpp/src/formats/vtp.cpp =====
// ===== begin cpp/src/formats/vtp_read.cpp =====
#include <cstdint>
#include <string>
#include <unordered_map>
#include <vector>

// External includes

// Project includes

namespace meshioplusplus {

namespace {

using detail::vtu_to_int64;

// compression: 0 = none, 1 = zlib. lzma/appended raise (handled by caller).
NDArray vtp_read_data_array(const pugi::xml_node& rDa, int compression, std::size_t hsz,
                            int& rNumComponents) {
    std::string fmt = rDa.attribute("format").as_string("ascii");
    DType dt = detail::dtype_from_vtu(rDa.attribute("type").as_string());
    rNumComponents = rDa.attribute("NumberOfComponents").as_int(0);

    if (fmt == "ascii")
        return detail::vtu_parse_ascii(rDa.text().get(), dt);
    if (fmt == "binary")
        return detail::vtu_parse_binary(detail::vtu_strip(rDa.text().get()), dt, compression, hsz);
    throw ReadError("VTP '" + fmt + "' data is not supported by the C++ reader");
}

// One PolyData section's connectivity + VTK end-offsets.
struct VtpPiece {
    std::vector<std::int64_t> mConn;
    std::vector<std::int64_t> mOffsets;
    bool mPresent = false;
};

VtpPiece vtp_read_section(const pugi::xml_node& rSection, int compression, std::size_t hsz) {
    VtpPiece out;
    if (!rSection)
        return out;
    out.mPresent = true;
    for (pugi::xml_node da : rSection.children("DataArray")) {
        std::string name = da.attribute("Name").as_string();
        int nc = 0;
        NDArray arr = vtp_read_data_array(da, compression, hsz, nc);
        if (name == "connectivity")
            out.mConn = vtu_to_int64(arr);
        else if (name == "offsets")
            out.mOffsets = vtu_to_int64(arr);
    }
    return out;
}

}  // namespace

Mesh read_vtp(const std::string& rPath) {
    pugi::xml_document doc;
    pugi::xml_parse_result res = doc.load_file(rPath.c_str());
    if (!res)
        throw ReadError(std::string("VTP XML parse failed: ") + res.description());

    pugi::xml_node root = doc.child("VTKFile");
    if (!root)
        throw ReadError("Expected tag 'VTKFile'");
    if (std::string(root.attribute("type").as_string()) != "PolyData")
        throw ReadError("Expected type PolyData");

    int compression = 0;  // 0 none, 1 zlib
    std::string compressor = root.attribute("compressor").as_string("");
    if (compressor == "vtkZLibDataCompressor")
        compression = 1;
    else if (compressor == "vtkLZMADataCompressor")
        throw ReadError("lzma-compressed VTP not supported by the C++ reader");
    else if (!compressor.empty())
        throw ReadError("Unknown VTP compressor '" + compressor + "'");

    std::string header_type = root.attribute("header_type").as_string("UInt32");
    std::size_t hsz = (header_type == "UInt64") ? 8 : 4;

    pugi::xml_node grid = root.child("PolyData");
    if (!grid)
        throw ReadError("No PolyData found");

    // Appended data is not handled here -> let the Python reader take over.
    if (grid.parent().child("AppendedData") || root.child("AppendedData"))
        throw ReadError("appended VTP data not supported by the C++ reader");

    pugi::xml_node piece = grid.child("Piece");
    if (!piece)
        throw ReadError("No Piece found");
    // A single piece is supported; multiple pieces -> Python reader.
    if (piece.next_sibling("Piece"))
        throw ReadError("multi-piece VTP not supported by the C++ reader");

    std::size_t num_points =
        static_cast<std::size_t>(piece.attribute("NumberOfPoints").as_ullong());

    Mesh mesh;
    std::unordered_map<std::string, NDArray> cell_data_raw;

    for (pugi::xml_node child : piece.children()) {
        std::string tag = child.name();
        if (tag == "Points") {
            pugi::xml_node da = child.child("DataArray");
            int nc = 0;
            NDArray pts = vtp_read_data_array(da, compression, hsz, nc);
            if (nc <= 0)
                nc = 3;
            pts.Reshape({num_points, static_cast<std::size_t>(nc)});
            mesh.AssignPoints(std::move(pts));
        } else if (tag == "PointData") {
            for (pugi::xml_node da : child.children("DataArray")) {
                int nc = 0;
                std::string name = da.attribute("Name").as_string();
                NDArray arr = vtp_read_data_array(da, compression, hsz, nc);
                if (nc > 1)
                    arr.Reshape({arr.Size() / nc, static_cast<std::size_t>(nc)});
                mesh.AddPointData(name, std::move(arr));
            }
        } else if (tag == "CellData") {
            for (pugi::xml_node da : child.children("DataArray")) {
                int nc = 0;
                std::string name = da.attribute("Name").as_string();
                NDArray arr = vtp_read_data_array(da, compression, hsz, nc);
                if (nc > 1)
                    arr.Reshape({arr.Size() / nc, static_cast<std::size_t>(nc)});
                cell_data_raw.emplace(name, std::move(arr));
            }
        }
    }

    VtpPiece verts = vtp_read_section(piece.child("Verts"), compression, hsz);
    VtpPiece lines = vtp_read_section(piece.child("Lines"), compression, hsz);
    VtpPiece polys = vtp_read_section(piece.child("Polys"), compression, hsz);
    VtpPiece strips = vtp_read_section(piece.child("Strips"), compression, hsz);
    if (!strips.mOffsets.empty())
        throw ReadError("triangle-strip VTP cells not supported by the C++ reader");

    // Concatenate sections in VTK's canonical PolyData cell order (Verts,
    // Lines, Polys), synthesizing a VTK type id per row so the shared
    // reconstruction (detail/vtk_cells.hpp) can build the blocks and split
    // cell_data.
    std::vector<std::int64_t> conn, offsets, types;
    auto append_section = [&](const VtpPiece& rSec, int kind) {
        const std::int64_t conn_base = static_cast<std::int64_t>(conn.size());
        std::int64_t prev = 0;
        for (std::int64_t end : rSec.mOffsets) {
            const std::int64_t sz = end - prev;
            prev = end;
            std::int64_t vtk_type = 0;
            if (kind == 0) {
                if (sz != 1)
                    throw ReadError("poly-vertex VTP cells not supported by the C++ reader");
                vtk_type = 1;  // VTK_VERTEX
            } else if (kind == 1) {
                if (sz != 2)
                    throw ReadError("poly-line VTP cells not supported by the C++ reader");
                vtk_type = 3;  // VTK_LINE
            } else {
                vtk_type = sz == 3 ? 5 : sz == 4 ? 9 : 7;  // triangle / quad / polygon
            }
            types.push_back(vtk_type);
            offsets.push_back(conn_base + end);
        }
        conn.insert(conn.end(), rSec.mConn.begin(), rSec.mConn.end());
    };
    append_section(verts, 0);
    append_section(lines, 1);
    append_section(polys, 2);

    detail::reconstruct_cells(conn.data(), offsets, types, cell_data_raw, mesh);
    return mesh;
}

}  // namespace meshioplusplus
// ===== end cpp/src/formats/vtp_read.cpp =====
// ===== begin cpp/src/formats/vtu.cpp =====
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <fstream>
#include <string>
#include <vector>

// Project includes

namespace meshioplusplus {

namespace {

using detail::cols;
using detail::read_double;
using detail::read_int;
using detail::vtu_ascii_double;
using detail::vtu_ascii_ndarray;
using detail::vtu_type_str;

}  // namespace

void write_vtu(const std::string& rPath, const Mesh& rMesh, bool binary, bool zlib) {
    for (const auto cb : rMesh.CellRange()) {
        if (cb.Type().rfind("polyhedron", 0) == 0)
            throw WriteError("C++ VTU writer does not support polyhedron cells");
    }

    std::ofstream os(rPath, std::ios::binary);
    if (!os)
        throw WriteError("Could not open file for writing: " + rPath);

    const NDArray& points = rMesh.Points();
    const std::size_t num_points = rMesh.NumPoints();
    const std::size_t dim = rMesh.PointDim();
    const std::size_t pt_isz = dtype_size(points.Dtype());

    std::size_t total_cells = 0;
    for (const auto cb : rMesh.CellRange())
        total_cells += cb.NumCells();

    const char* fmt = binary ? "binary" : "ascii";

    auto da_header = [&](const char* type, const std::string& name, int ncomp) {
        os << "<DataArray type=\"" << type << "\" Name=\"" << name << "\"";
        if (ncomp > 0)
            os << " NumberOfComponents=\"" << ncomp << "\"";
        os << " format=\"" << fmt << "\">\n";
    };
    auto emit_bin = [&](const unsigned char* d, std::size_t n) {
        os << detail::vtu_encode_binary(d, n, zlib) << "\n";
    };

    os << "<?xml version=\"1.0\"?>\n";
    os << "<VTKFile type=\"UnstructuredGrid\" version=\"0.1\" "
          "byte_order=\"LittleEndian\"";
    if (binary && zlib)
        os << " compressor=\"vtkZLibDataCompressor\"";
    os << ">\n";
    os << "<!--This file was created by meshio++ (C++ core)-->\n";
    os << "<UnstructuredGrid>\n";
    os << "<Piece NumberOfPoints=\"" << num_points << "\" NumberOfCells=\"" << total_cells
       << "\">\n";

    // Points (3 components; pad 2D with zero z).
    os << "<Points>\n";
    da_header(vtu_type_str(points.Dtype()), "Points", 3);
    if (binary) {
        // Pre-sized buffer (zero-filled -> the padded z stays 0), indexed
        // byte writes -> parallel over points.
        std::vector<unsigned char> buf(num_points * 3 * pt_isz, 0);
        const auto* src = reinterpret_cast<const unsigned char*>(points.Data());
        parallel_for(num_points, [&](std::size_t r) {
            for (std::size_t c = 0; c < dim && c < 3; ++c)
                std::memcpy(buf.data() + (r * 3 + c) * pt_isz, src + (r * dim + c) * pt_isz,
                            pt_isz);
        });
        emit_bin(buf.data(), buf.size());
    } else {
        for (std::size_t r = 0; r < num_points; ++r)
            for (std::size_t c = 0; c < 3; ++c)
                vtu_ascii_double(os, (c < dim) ? read_double(points, r * dim + c) : 0.0);
    }
    os << "</DataArray>\n</Points>\n";

    if (rMesh.NumCellBlocks() != 0) {
        // Build connectivity / offsets / types (Int64) into pre-sized arrays.
        // Per-block offsets are closed-form (conn_base + (r+1)*k), so rows are
        // independent and each block fills in parallel.
        const auto& tmap = meshio_to_vtk_type();
        std::size_t total_conn = 0, ncells = 0;
        for (const auto cb : rMesh.CellRange()) {
            total_conn += cb.NumCells() * cols(cb.Conn());
            ncells += cb.NumCells();
        }
        std::vector<std::int64_t> connectivity(total_conn), offsets(ncells), types(ncells);
        std::size_t conn_base = 0, cell_base = 0;
        for (const auto cb : rMesh.CellRange()) {
            const NDArray& conn = cb.Conn();
            const std::size_t nc = cb.NumCells();
            const std::size_t k = cols(conn);
            std::vector<int> order = meshio_to_vtk_order(cb.Type());
            auto it = tmap.find(cb.Type());
            if (it == tmap.end())
                throw WriteError("Unknown cell type for VTU: " + cb.Type());
            const std::int64_t vtk_type = it->second;
            parallel_for(nc, [&](std::size_t r) {
                for (std::size_t j = 0; j < k; ++j) {
                    std::size_t col = order.empty() ? j : static_cast<std::size_t>(order[j]);
                    connectivity[conn_base + r * k + j] = read_int(conn, r * k + col);
                }
                offsets[cell_base + r] = static_cast<std::int64_t>(conn_base + (r + 1) * k);
                types[cell_base + r] = vtk_type;
            });
            conn_base += nc * k;
            cell_base += nc;
        }

        auto emit_i64 = [&](const char* name, const std::vector<std::int64_t>& v) {
            da_header("Int64", name, 0);
            if (binary) {
                emit_bin(reinterpret_cast<const unsigned char*>(v.data()),
                         v.size() * sizeof(std::int64_t));
            } else {
                for (std::int64_t x : v)
                    os << x << '\n';
            }
            os << "</DataArray>\n";
        };

        os << "<Cells>\n";
        emit_i64("connectivity", connectivity);
        emit_i64("offsets", offsets);
        emit_i64("types", types);
        os << "</Cells>\n";
    }

    if (rMesh.NumPointData() != 0) {
        os << "<PointData>\n";
        for (const auto& name : rMesh.PointDataNames()) {
            const NDArray& d = rMesh.PointData(name);
            int ncomp = (d.Shape().size() == 2) ? static_cast<int>(cols(d)) : 0;
            da_header(vtu_type_str(d.Dtype()), name, ncomp);
            if (binary)
                emit_bin(reinterpret_cast<const unsigned char*>(d.Data()), d.Nbytes());
            else
                vtu_ascii_ndarray(os, d);
            os << "</DataArray>\n";
        }
        os << "</PointData>\n";
    }

    if (rMesh.NumCellData() != 0) {
        os << "<CellData>\n";
        for (const auto& name : rMesh.CellDataNames()) {
            const std::size_t nblocks = rMesh.CellDataNumBlocks(name);
            if (nblocks == 0)
                continue;
            const NDArray& first = rMesh.CellData(name, 0);
            int ncomp = (first.Shape().size() == 2) ? static_cast<int>(cols(first)) : 0;
            da_header(vtu_type_str(first.Dtype()), name, ncomp);
            if (binary) {
                std::vector<unsigned char> buf;
                for (std::size_t bi = 0; bi < nblocks; ++bi) {
                    const NDArray& blk = rMesh.CellData(name, bi);
                    const unsigned char* p = reinterpret_cast<const unsigned char*>(blk.Data());
                    buf.insert(buf.end(), p, p + blk.Nbytes());
                }
                emit_bin(buf.data(), buf.size());
            } else {
                for (std::size_t bi = 0; bi < nblocks; ++bi)
                    vtu_ascii_ndarray(os, rMesh.CellData(name, bi));
            }
            os << "</DataArray>\n";
        }
        os << "</CellData>\n";
    }

    os << "</Piece>\n</UnstructuredGrid>\n</VTKFile>\n";
}

}  // namespace meshioplusplus
// ===== end cpp/src/formats/vtu.cpp =====
// ===== begin cpp/src/formats/vtu_read.cpp =====
#include <cctype>
#include <cstdint>
#include <cstdlib>
#include <cstring>
#include <string>
#include <unordered_map>
#include <vector>

// External includes

// Project includes

namespace meshioplusplus {

namespace {

using detail::vtu_to_int64;

// compression: 0 = none, 1 = zlib. lzma/appended raise (handled by caller).
NDArray vtu_read_data_array(const pugi::xml_node& rDa, int compression, std::size_t hsz,
                            int& rNumComponents) {
    std::string fmt = rDa.attribute("format").as_string("ascii");
    DType dt = detail::dtype_from_vtu(rDa.attribute("type").as_string());
    rNumComponents = rDa.attribute("NumberOfComponents").as_int(0);

    if (fmt == "ascii")
        return detail::vtu_parse_ascii(rDa.text().get(), dt);
    if (fmt == "binary")
        return detail::vtu_parse_binary(detail::vtu_strip(rDa.text().get()), dt, compression, hsz);
    throw ReadError("VTU '" + fmt + "' data is not supported by the C++ reader");
}

}  // namespace

Mesh read_vtu(const std::string& rPath) {
    pugi::xml_document doc;
    pugi::xml_parse_result res = doc.load_file(rPath.c_str());
    if (!res)
        throw ReadError(std::string("VTU XML parse failed: ") + res.description());

    pugi::xml_node root = doc.child("VTKFile");
    if (!root)
        throw ReadError("Expected tag 'VTKFile'");
    if (std::string(root.attribute("type").as_string()) != "UnstructuredGrid")
        throw ReadError("Expected type UnstructuredGrid");

    int compression = 0;  // 0 none, 1 zlib
    std::string compressor = root.attribute("compressor").as_string("");
    if (compressor == "vtkZLibDataCompressor")
        compression = 1;
    else if (compressor == "vtkLZMADataCompressor")
        throw ReadError("lzma-compressed VTU not supported by the C++ reader");
    else if (!compressor.empty())
        throw ReadError("Unknown VTU compressor '" + compressor + "'");

    std::string header_type = root.attribute("header_type").as_string("UInt32");
    std::size_t hsz = (header_type == "UInt64") ? 8 : 4;

    pugi::xml_node grid = root.child("UnstructuredGrid");
    if (!grid)
        throw ReadError("No UnstructuredGrid found");

    // Appended data is not handled here -> let the Python reader take over.
    if (grid.parent().child("AppendedData") || root.child("AppendedData"))
        throw ReadError("appended VTU data not supported by the C++ reader");

    pugi::xml_node piece = grid.child("Piece");
    if (!piece)
        throw ReadError("No Piece found");
    // A single piece is supported; multiple pieces -> Python reader.
    if (piece.next_sibling("Piece"))
        throw ReadError("multi-piece VTU not supported by the C++ reader");

    std::size_t num_points =
        static_cast<std::size_t>(piece.attribute("NumberOfPoints").as_ullong());

    Mesh mesh;
    std::vector<std::int64_t> conn, offsets, types;
    std::unordered_map<std::string, NDArray> cell_data_raw;

    for (pugi::xml_node child : piece.children()) {
        std::string tag = child.name();
        if (tag == "Points") {
            pugi::xml_node da = child.child("DataArray");
            int nc = 0;
            NDArray pts = vtu_read_data_array(da, compression, hsz, nc);
            if (nc <= 0)
                nc = 3;
            pts.Reshape({num_points, static_cast<std::size_t>(nc)});
            mesh.AssignPoints(std::move(pts));
        } else if (tag == "Cells") {
            for (pugi::xml_node da : child.children("DataArray")) {
                int nc = 0;
                std::string name = da.attribute("Name").as_string();
                NDArray arr = vtu_read_data_array(da, compression, hsz, nc);
                if (name == "connectivity")
                    conn = vtu_to_int64(arr);
                else if (name == "offsets")
                    offsets = vtu_to_int64(arr);
                else if (name == "types")
                    types = vtu_to_int64(arr);
                else if (name == "faces" || name == "faceoffsets")
                    throw ReadError("polyhedron VTU not supported by the C++ reader");
            }
        } else if (tag == "PointData") {
            for (pugi::xml_node da : child.children("DataArray")) {
                int nc = 0;
                std::string name = da.attribute("Name").as_string();
                NDArray arr = vtu_read_data_array(da, compression, hsz, nc);
                if (nc > 1)
                    arr.Reshape({arr.Size() / nc, static_cast<std::size_t>(nc)});
                mesh.AddPointData(name, std::move(arr));
            }
        } else if (tag == "CellData") {
            for (pugi::xml_node da : child.children("DataArray")) {
                int nc = 0;
                std::string name = da.attribute("Name").as_string();
                NDArray arr = vtu_read_data_array(da, compression, hsz, nc);
                if (nc > 1)
                    arr.Reshape({arr.Size() / nc, static_cast<std::size_t>(nc)});
                cell_data_raw.emplace(name, std::move(arr));
            }
        }
    }

    detail::reconstruct_cells(conn.data(), offsets, types, cell_data_raw, mesh);
    return mesh;
}

}  // namespace meshioplusplus
// ===== end cpp/src/formats/vtu_read.cpp =====
